-- =====================================================================
-- Song Clustering & Recommendation Engine — SQLite Analysis Script
-- Source: songs_clean.csv (1,941 unique tracks, Spotify 2000-2020 sample)
-- Clusters were computed in Python (K-Means, k=6, see companion notebook)
-- and are stored here as pre-computed columns (`cluster`, `cluster_name`).
-- =====================================================================


-- =====================================================================
-- SECTION 1: TABLE SCHEMA
-- =====================================================================

DROP TABLE IF EXISTS songs;

CREATE TABLE songs (
    song_id            INTEGER PRIMARY KEY,
    artist             TEXT NOT NULL,
    song               TEXT NOT NULL,
    year               INTEGER NOT NULL,
    genre              TEXT,               -- full, possibly multi-label genre string
    primary_genre      TEXT,               -- first tag from `genre`
    explicit           INTEGER,            -- 0/1
    popularity         INTEGER,            -- Spotify popularity score, 0-100
    duration_ms        INTEGER,
    duration_min       REAL,
    danceability       REAL,
    energy             REAL,
    key                INTEGER,
    loudness           REAL,
    mode               INTEGER,            -- 0 = minor, 1 = major
    speechiness        REAL,
    acousticness       REAL,
    instrumentalness   REAL,
    liveness           REAL,
    valence            REAL,
    tempo              REAL,
    cluster            INTEGER,            -- K-Means cluster id (0-5)
    cluster_name       TEXT                -- human-readable cluster label
);

CREATE INDEX idx_songs_cluster ON songs(cluster);
CREATE INDEX idx_songs_genre   ON songs(primary_genre);
CREATE INDEX idx_songs_artist  ON songs(artist);


-- =====================================================================
-- SECTION 2: SEED DATA
-- 1,941 INSERT statements generated directly from songs_clean.csv.
-- (Full statements live in seed_data.sql — imported below for brevity;
--  see the companion file included with this script.)
-- =====================================================================



-- =====================================================================
-- SECTION 3: ANALYTICAL QUERIES
-- =====================================================================

-- ---------------------------------------------------------------------
-- 3.1  Cluster sizes and share of catalog
-- ---------------------------------------------------------------------
SELECT
    cluster_name,
    COUNT(*)                                       AS n_songs,
    ROUND(100.0 * COUNT(*) / (SELECT COUNT(*) FROM songs), 1) AS pct_of_catalog
FROM songs
GROUP BY cluster_name
ORDER BY n_songs DESC;


-- ---------------------------------------------------------------------
-- 3.2  Cluster audio-feature profile (mirrors notebook Section 6)
-- ---------------------------------------------------------------------
SELECT
    cluster_name,
    ROUND(AVG(danceability), 3)      AS avg_danceability,
    ROUND(AVG(energy), 3)            AS avg_energy,
    ROUND(AVG(loudness), 3)          AS avg_loudness,
    ROUND(AVG(speechiness), 3)       AS avg_speechiness,
    ROUND(AVG(acousticness), 3)      AS avg_acousticness,
    ROUND(AVG(instrumentalness), 3)  AS avg_instrumentalness,
    ROUND(AVG(liveness), 3)          AS avg_liveness,
    ROUND(AVG(valence), 3)           AS avg_valence,
    ROUND(AVG(tempo), 1)             AS avg_tempo
FROM songs
GROUP BY cluster_name
ORDER BY cluster_name;


-- ---------------------------------------------------------------------
-- 3.3  Dominant genre per cluster (genre purity, mirrors notebook 7)
-- ---------------------------------------------------------------------
WITH genre_counts AS (
    SELECT
        cluster_name,
        primary_genre,
        COUNT(*) AS n,
        ROUND(100.0 * COUNT(*) / SUM(COUNT(*)) OVER (PARTITION BY cluster_name), 1) AS pct
    FROM songs
    GROUP BY cluster_name, primary_genre
),
ranked AS (
    SELECT *, ROW_NUMBER() OVER (PARTITION BY cluster_name ORDER BY n DESC) AS rnk
    FROM genre_counts
)
SELECT cluster_name, primary_genre AS top_genre, n AS song_count, pct AS top_genre_share_pct
FROM ranked
WHERE rnk = 1
ORDER BY top_genre_share_pct DESC;


-- ---------------------------------------------------------------------
-- 3.4  Popularity by cluster (supports the ANOVA test in the notebook —
--      notebook finds p=0.32, i.e. NOT statistically significant)
-- ---------------------------------------------------------------------
SELECT
    cluster_name,
    COUNT(*)                     AS n_songs,
    ROUND(AVG(popularity), 2)    AS avg_popularity,
    ROUND(MIN(popularity), 0)    AS min_popularity,
    ROUND(MAX(popularity), 0)    AS max_popularity
FROM songs
GROUP BY cluster_name
ORDER BY avg_popularity DESC;


-- ---------------------------------------------------------------------
-- 3.5  Cluster x genre cross-tab (raw counts feeding the chi-square test
--      in the notebook — p ≈ 4.8e-51, clusters ARE genre-associated)
-- ---------------------------------------------------------------------
SELECT
    cluster_name,
    SUM(CASE WHEN primary_genre = 'pop' THEN 1 ELSE 0 END)              AS pop,
    SUM(CASE WHEN primary_genre = 'hip hop' THEN 1 ELSE 0 END)          AS hip_hop,
    SUM(CASE WHEN primary_genre = 'rock' THEN 1 ELSE 0 END)             AS rock,
    SUM(CASE WHEN primary_genre = 'Dance/Electronic' THEN 1 ELSE 0 END) AS dance_electronic,
    SUM(CASE WHEN primary_genre = 'Unknown' THEN 1 ELSE 0 END)          AS unknown,
    COUNT(*) - (
        SUM(CASE WHEN primary_genre = 'pop' THEN 1 ELSE 0 END) +
        SUM(CASE WHEN primary_genre = 'hip hop' THEN 1 ELSE 0 END) +
        SUM(CASE WHEN primary_genre = 'rock' THEN 1 ELSE 0 END) +
        SUM(CASE WHEN primary_genre = 'Dance/Electronic' THEN 1 ELSE 0 END) +
        SUM(CASE WHEN primary_genre = 'Unknown' THEN 1 ELSE 0 END)
    ) AS other
FROM songs
GROUP BY cluster_name
ORDER BY cluster_name;


-- ---------------------------------------------------------------------
-- 3.6  RECOMMENDATION QUERY — candidate generation layer
--      In production, this is the layer a database/service would run:
--      filter to the seed song's cluster + business rules (here,
--      exclude explicit tracks), ranked by popularity as a simple
--      fallback. Fine-grained re-ranking by audio similarity is the
--      model-serving layer's job (see notebook Section 9).
-- ---------------------------------------------------------------------
WITH seed AS (
    SELECT song_id, cluster FROM songs
    WHERE artist = 'Dua Lipa' AND song = "Don't Start Now"
)
SELECT s.artist, s.song, s.cluster_name, s.popularity
FROM songs s, seed
WHERE s.cluster = seed.cluster
  AND s.song_id != seed.song_id
  AND s.explicit = 0
ORDER BY s.popularity DESC
LIMIT 10;


-- ---------------------------------------------------------------------
-- 3.7  RECOMMENDATION QUERY — nearest-neighbor by audio similarity
--      A pure-SQL approximation of the notebook's cosine-similarity
--      recommender: min-max normalizes loudness & tempo inline (the
--      two features not already on a ~0-1 scale), then ranks the
--      seed song's own cluster by squared Euclidean distance across
--      all 9 clustering features. On the same seed song, 3 of its
--      top 5 matches (Imagine Dragons "Believer", The Shapeshifters
--      "Lola's Theme", Jennifer Lopez "Dance Again") agree with the
--      notebook's cosine-similarity ranking — confirming the two
--      methods converge on the same sonic neighborhood.
-- ---------------------------------------------------------------------
WITH bounds AS (
    SELECT MIN(loudness) AS lo_min, MAX(loudness) AS lo_max,
           MIN(tempo)    AS te_min, MAX(tempo)    AS te_max
    FROM songs
),
seed AS (
    SELECT song_id, cluster, danceability, energy, speechiness, acousticness,
           instrumentalness, liveness, valence,
           (loudness - (SELECT lo_min FROM bounds)) / ((SELECT lo_max FROM bounds) - (SELECT lo_min FROM bounds)) AS loudness_n,
           (tempo    - (SELECT te_min FROM bounds)) / ((SELECT te_max FROM bounds) - (SELECT te_min FROM bounds)) AS tempo_n
    FROM songs
    WHERE artist = 'Dua Lipa' AND song = "Don't Start Now"
)
SELECT
    s.artist, s.song,
    ROUND(
        (s.danceability - seed.danceability) * (s.danceability - seed.danceability) +
        (s.energy - seed.energy) * (s.energy - seed.energy) +
        (((s.loudness - (SELECT lo_min FROM bounds)) / ((SELECT lo_max FROM bounds) - (SELECT lo_min FROM bounds))) - seed.loudness_n) *
        (((s.loudness - (SELECT lo_min FROM bounds)) / ((SELECT lo_max FROM bounds) - (SELECT lo_min FROM bounds))) - seed.loudness_n) +
        (s.speechiness - seed.speechiness) * (s.speechiness - seed.speechiness) +
        (s.acousticness - seed.acousticness) * (s.acousticness - seed.acousticness) +
        (s.instrumentalness - seed.instrumentalness) * (s.instrumentalness - seed.instrumentalness) +
        (s.liveness - seed.liveness) * (s.liveness - seed.liveness) +
        (s.valence - seed.valence) * (s.valence - seed.valence) +
        (((s.tempo - (SELECT te_min FROM bounds)) / ((SELECT te_max FROM bounds) - (SELECT te_min FROM bounds))) - seed.tempo_n) *
        (((s.tempo - (SELECT te_min FROM bounds)) / ((SELECT te_max FROM bounds) - (SELECT te_min FROM bounds))) - seed.tempo_n)
    , 4) AS distance
FROM songs s, seed
WHERE s.cluster = seed.cluster
  AND s.song_id != seed.song_id
ORDER BY distance ASC
LIMIT 5;
